import random, statistics, math, sys
def run(seed):
    r=random.Random(seed)
    def groups(n):
        labels=[0,1]*(n//2)
        r.shuffle(labels)
        return [(tuple(r.random() for _ in range(6)),y) for y in labels]
    def obs(g):
        x,y=g
        return (tuple(a+r.uniform(-.005,.005) for a in x),y)
    base,spare,test,audit=map(groups,[80,40,40,60])
    base,spare,twins,held,audit=map(lambda v:list(map(obs,v)),[base,spare,test,test,audit])
    def acc(train,ev):
        return sum(min(train,key=lambda t: math.dist(t[0],x))[1]==y for x,y in ev)/len(ev)
    return [acc(train,ev) for train in (base+twins,base+spare) for ev in (held,audit)]
rows=[run(s) for s in range(30)]
print('seed0',rows[0], 'means',list(map(statistics.mean,zip(*rows))), 'range',[(min(c),max(c)) for c in zip(*rows)])
print(sys.version)
